<script setup lang="ts">
/**
 * FusionTimerButton
 * The clock button in the top bar. Plain when nothing runs, green with the running time when a timer is on.
 */
import { Clock } from "@lucide/vue";

withDefaults(
    defineProps<{
        running?: boolean;
        /** Running time, for example "00:42:17". Shown while running. */
        elapsed?: string;
        /** For the dark top bar. */
        onDark?: boolean;
        ariaLabel?: string;
        expanded?: boolean;
    }>(),
    { running: false, elapsed: "", onDark: true, ariaLabel: "Time tracker", expanded: false },
);

defineEmits<{ (e: "click", ev: MouseEvent): void }>();
</script>

<template>
    <button
        type="button"
        class="fu-timerbtn"
        :class="{ 'is-running': running, 'is-dark': onDark }"
        :aria-label="running ? `${ariaLabel}, running ${elapsed}` : ariaLabel"
        aria-haspopup="dialog"
        :aria-expanded="expanded"
        @click="$emit('click', $event)"
    >
        <Clock :size="18" />
        <b v-if="running" class="fu-timerbtn__time">{{ elapsed }}</b>
        <span v-if="running" class="fu-timerbtn__dot" aria-hidden="true" />
    </button>
</template>

