<script setup lang="ts">
/**
 * FusionTreeTable
 * A collapsible tree table built on Tabulator, styled to match FusionListView.
 * Controlled: the parent owns data, selection and column order.
 */
import {
    computed,
    getCurrentInstance,
    h,
    nextTick,
    onBeforeUnmount,
    onMounted,
    ref,
    render,
    useSlots,
    watch,
    type Component,
    type VNode,
} from "vue";
import {
    Tabulator,
    DataTreeModule,
    FormatModule,
    FrozenColumnsModule,
    GroupRowsModule,
    InteractionModule,
    MoveColumnsModule,
    ResizeColumnsModule,
    ResizeTableModule,
    SelectRowModule,
    SortModule,
    type CellComponent,
    type GroupComponent,
    type ColumnDefinition,
    type RowComponent,
} from "tabulator-tables";
import { Ellipsis, Plus } from "@lucide/vue";
import FusionActionButton from "../actionButton/FusionActionButton.vue";
import DropdownMenu from "../dropdownMenu/DropdownMenu.vue";
import "tabulator-tables/dist/css/tabulator.min.css";
import "./TreeTable.scss";
import type { TreeTableDropPosition, TreeTableMove } from "./treeTableUtils";
export type { TreeTableDropPosition, TreeTableMove } from "./treeTableUtils";

Tabulator.registerModule([
    DataTreeModule,
    FormatModule,
    FrozenColumnsModule,
    GroupRowsModule,
    InteractionModule,
    MoveColumnsModule,
    ResizeColumnsModule,
    ResizeTableModule,
    SelectRowModule,
    SortModule,
]);

export interface TreeTableColumn {
    /** Field name on each row object. Also the slot suffix: `cell-<key>`. */
    key: string;
    label: string;
    /** Pixel width. Omit for flexible. */
    width?: number;
    minWidth?: number;
    textAlign?: "left" | "center" | "right";
    sortable?: boolean;
    visible?: boolean;
    resizable?: boolean;
}

export type TreeTableId = string | number;

export interface TreeTableGroupAction {
    /** Sent back in `group-action`. */
    key: string;
    label: string;
    icon?: Component;
    disabled?: boolean;
    /** Draw a divider line above this action. */
    dividerBefore?: boolean;
}

export interface TreeTableGroup {
    id: TreeTableId;
    label: string;
    [extra: string]: any;
}

export interface TreeTableSort {
    key: string;
    dir: "asc" | "desc";
}

const props = withDefaults(
    defineProps<{
        columns: TreeTableColumn[];
        rows: Record<string, any>[];
        /** Unique id field on every row, including children. */
        idField?: string;
        /** Field holding each row's parent id (for example "parent_id"; null on top level tasks). Set it when your rows are flat, with no nested children. The table builds the tree itself. */
        parentField?: string;
        /** Field holding the child rows. */
        childrenField?: string;
        /** Field on each TOP LEVEL row that holds its group's id (for example "group_id"). Subtasks don't carry it: they only have a parent. Turns on full width group bars. */
        groupField?: string;
        /** The groups, in order. Lets empty groups show. Each `id` matches the value in the `groupField` of its top level tasks. */
        groups?: TreeTableGroup[];
        groupStartOpen?: boolean;
        /** Actions in each group bar's "..." menu. A group can hide some with `hiddenActions: ['archive']` in its own data. */
        groupActions?: TreeTableGroupAction[];
        /** Show a "+" in each group bar. Emits `add-task`. */
        groupAdd?: boolean;
        groupAddLabel?: string;
        /** Column that shows the expand/collapse arrow. Defaults to the first visible column. */
        treeColumn?: string;
        /** Keep the tree column first and in place (it stays visible while scrolling sideways). Other columns can still be moved. */
        pinTreeColumn?: boolean;
        selectable?: boolean;
        /** Selected row keys (v-model). */
        selectedIds?: TreeTableId[];
        /** Selecting a parent also selects its children. */
        propagateSelection?: boolean;
        startExpanded?: boolean;
        movableColumns?: boolean;
        resizableColumns?: boolean;
        sortable?: boolean;
        /** Rows can be dragged by the grip to reorder or nest. Emits `row-move`; the parent updates its rows. */
        draggableRows?: boolean;
        /** Indent per tree level in px. */
        indent?: number;
        /** Keep the column header in view while the page (or the scrolling area around the table) scrolls. Not needed with a fixed `height`, where the header never leaves. */
        stickyHeader?: boolean;
        /** Gap from the top for the sticky header, in px. Use it to clear a fixed top bar. */
        stickyOffset?: number;
        /** Fixed height (px number or CSS string). Omit to grow with content. */
        height?: number | string;
        loading?: boolean;
        /** Number of placeholder rows shown while loading. */
        skeletonRows?: number;
        emptyText?: string;
    }>(),
    {
        idField: "id",
        childrenField: "children",
        stickyHeader: false,
        stickyOffset: 0,
        pinTreeColumn: true,
        groupStartOpen: true,
        groupAdd: false,
        groupAddLabel: "Add task",
        selectable: true,
        selectedIds: () => [],
        propagateSelection: true,
        startExpanded: true,
        movableColumns: true,
        resizableColumns: true,
        sortable: true,
        draggableRows: true,
        indent: 22,
        loading: false,
        skeletonRows: 8,
        emptyText: "Nothing to show",
    },
);

const emit = defineEmits<{
    (e: "update:selectedIds", keys: TreeTableId[]): void;
    (e: "row-click", row: Record<string, any>): void;
    (e: "columns-reordered", keys: string[]): void;
    (e: "column-resized", payload: { key: string; width: number }): void;
    (e: "sort-change", sort: TreeTableSort | null): void;
    (e: "row-move", move: TreeTableMove): void;
    (e: "group-action", payload: { groupId: TreeTableId; action: string }): void;
    (e: "add-task", payload: { groupId: TreeTableId }): void;
    (e: "row-expanded", row: Record<string, any>): void;
    (e: "row-collapsed", row: Record<string, any>): void;
}>();

const slots = useSlots();
const instance = getCurrentInstance();
const host = ref<HTMLElement | null>(null);
let table: Tabulator | null = null;
let built = false;
let syncingSelection = false;
const mounted = new Set<HTMLElement>();
const selectedCount = ref(0);
const scrolled = ref(false);
let holderEl: HTMLElement | null = null;

function onHolderScroll() {
    scrolled.value = (holderEl?.scrollLeft ?? 0) > 0;
    /* Open menus (group actions, dropdowns) are pinned to the page, so close them when the table moves under them */
    document.dispatchEvent(new CustomEvent("close-all-dropdowns"));
}

const visibleColumns = computed(() => props.columns.filter((c) => c.visible !== false));
/* The tree column is fixed when the table is created, so dragging columns around never moves the tree to another column. */
const initialTreeKey = props.treeColumn ?? props.columns.find((c) => c.visible !== false)?.key;
const treeKey = computed(() => {
    const wanted = props.treeColumn ?? initialTreeKey;
    return visibleColumns.value.some((c) => c.key === wanted) ? wanted : visibleColumns.value[0]?.key;
});

/* ---------- Vue slot content inside Tabulator cells ---------- */

function levelOf(row: RowComponent): number {
    let level = 0;
    let parent = row.getTreeParent();
    while (parent) {
        level++;
        parent = parent.getTreeParent();
    }
    return level;
}

/**
 * Unmount Vue content whose element has left the page. A cell's content is only cleaned up once its
 * row is gone from the table: rows inside a collapsed folder (or under a collapsed task) are detached
 * from the page too, but Tabulator re-attaches the same elements when they open again, so unmounting
 * them here left those rows blank.
 */
function pruneDetached() {
    let alive: Set<TreeTableId> | null = null;
    const rowAlive = (id: TreeTableId) => {
        if (!table) return false;
        if (!alive) {
            alive = new Set();
            walk(table.getRows(), (r) => alive!.add(idOf(r.getData())));
        }
        return alive.has(id);
    };
    mounted.forEach((el) => {
        if (el.isConnected) return;
        const rowId = (el as HTMLElement & { __fuRowId?: TreeTableId }).__fuRowId;
        if (rowId !== undefined && rowAlive(rowId)) return;
        render(null, el);
        mounted.delete(el);
    });
}

const CHEVRON_SIZE = 20;

function siblingsOf(row: RowComponent): RowComponent[] {
    const parent = row.getTreeParent();
    return parent ? parent.getTreeChildren() : [];
}

function hasNextSibling(row: RowComponent): boolean {
    const list = siblingsOf(row);
    const id = idOf(row.getData());
    const i = list.findIndex((r) => idOf(r.getData()) === id);
    return i > -1 && i < list.length - 1;
}

function makeLine(cls: string, style: Record<string, string>): HTMLElement {
    const el = document.createElement("span");
    el.className = cls;
    el.setAttribute("aria-hidden", "true");
    Object.assign(el.style, style);
    return el;
}

/** Draws the tree connector lines (vertical guides plus the curved elbow) for one row. */
function drawGuides(cell: CellComponent) {
    const el = cell.getElement();
    el.querySelectorAll(".fu-treetable__guide, .fu-treetable__elbow").forEach((n) => n.remove());
    const row = cell.getRow();
    const level = levelOf(row);
    if (!level) return;

    const base = parseFloat(getComputedStyle(el).paddingLeft) || 0;
    const indent = props.indent;
    const x = (depth: number) => base + (depth - 1) * indent + CHEVRON_SIZE / 2;

    /* chain[0] is the top-level ancestor, chain[level] is this row */
    const chain: RowComponent[] = [row];
    let p = row.getTreeParent();
    while (p) {
        chain.unshift(p);
        p = p.getTreeParent();
    }

    for (let depth = 1; depth < level; depth++) {
        if (hasNextSibling(chain[depth])) {
            el.appendChild(makeLine("fu-treetable__guide", { left: `${x(depth)}px` }));
        }
    }

    const isParent = row.getTreeChildren().length > 0;
    const run = indent - CHEVRON_SIZE / 2 + (isParent ? -2 : CHEVRON_SIZE - 4);
    if (hasNextSibling(row)) {
        el.appendChild(makeLine("fu-treetable__guide", { left: `${x(level)}px` }));
    }
    el.appendChild(makeLine("fu-treetable__elbow", { left: `${x(level)}px`, width: `${run}px` }));
}

function refreshGuides() {
    if (!table || !treeKey.value) return;
    const key = treeKey.value;
    walk(table.getRows(), (r) => {
        const c = r.getCell(key);
        if (c) drawGuides(c);
    });
}

function cellFormatter(col: TreeTableColumn) {
    return (cell: CellComponent, _params: unknown, onRendered: (fn: () => void) => void) => {
        const slot = (slots as Record<string, any>)[`cell-${col.key}`];
        const row = cell.getRow();
        const data = row.getData();
        const value = cell.getValue();
        let out: HTMLElement;
        if (!slot) {
            out = document.createElement("span");
            out.className = "fu-treetable__text";
            out.textContent = value == null ? "" : String(value);
        } else {
            out = document.createElement("div");
            out.className = "fu-treetable__slot";
            const vnode: VNode = h("span", { class: "fu-treetable__slot-inner" }, slot({ row: data, value, level: levelOf(row) }));
            if (instance) vnode.appContext = instance.appContext;
            render(vnode, out);
            (out as HTMLElement & { __fuRowId?: TreeTableId }).__fuRowId = idOf(data);
            mounted.add(out);
        }
        if (col.key === treeKey.value) {
            const kids = data[props.childrenField];
            if (!Array.isArray(kids) || !kids.length) out.classList.add("fu-treetable__leaf");
            onRendered(() => drawGuides(cell));
        }
        return out;
    };
}

const COL_GRIP_SVG =
    '<svg viewBox="0 0 16 16" width="12" height="12" aria-hidden="true"><g fill="currentColor"><circle cx="5.5" cy="3.5" r="1.2"/><circle cx="10.5" cy="3.5" r="1.2"/><circle cx="5.5" cy="8" r="1.2"/><circle cx="10.5" cy="8" r="1.2"/><circle cx="5.5" cy="12.5" r="1.2"/><circle cx="10.5" cy="12.5" r="1.2"/></g></svg>';

/** Header title with a grip that shows on hover, so it is clear the column can be dragged. */
function headerTitle(label: string, movable = true): HTMLElement {
    const wrap = document.createElement("span");
    wrap.className = "fu-treetable__col-title";
    {
        const grip = document.createElement("span");
        grip.className = `fu-treetable__col-grip${props.movableColumns && movable ? "" : " is-static"}`;
        grip.setAttribute("aria-hidden", "true");
        grip.innerHTML = COL_GRIP_SVG;
        wrap.appendChild(grip);
    }
    const text = document.createElement("span");
    text.textContent = label;
    wrap.appendChild(text);
    return wrap;
}

function buildColumns(): ColumnDefinition[] {
    let list = visibleColumns.value;
    if (props.pinTreeColumn && treeKey.value) {
        const tree = list.find((c) => c.key === treeKey.value);
        if (tree) list = [tree, ...list.filter((c) => c !== tree)];
    }
    return list.map((col) => ({
        title: col.label,
        field: col.key,
        width: col.width,
        minWidth: col.minWidth ?? 80,
        hozAlign: col.textAlign ?? "left",
        headerHozAlign: col.textAlign ?? "left",
        headerSort: props.sortable && col.sortable !== false,
        headerSortStartingDir: "asc",
        resizable: props.resizableColumns && col.resizable !== false,
        frozen: props.pinTreeColumn && col.key === treeKey.value,
        titleFormatter: () => headerTitle(col.label, !(props.pinTreeColumn && col.key === treeKey.value)),
        formatter: cellFormatter(col),
    }));
}

function chevron(open: boolean): HTMLElement {
    const el = document.createElement("span");
    el.className = `fu-treetable__chevron${open ? " is-open" : ""}`;
    el.setAttribute("role", "button");
    el.setAttribute("aria-label", open ? "Collapse row" : "Expand row");
    el.innerHTML =
        '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><path d="M6 3.5 10.5 8 6 12.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    return el;
}

/* ---------- Data ---------- */

function idOf(row: Record<string, any>): TreeTableId {
    return row[props.idField];
}

/** Flat rows (id + parent id) become a tree. Sibling order follows the order of the array. */
function toTree(rows: Record<string, any>[]): Record<string, any>[] {
    const pk = props.parentField as string;
    const nodes = new Map<TreeTableId, Record<string, any>>();
    rows.forEach((r) => nodes.set(idOf(r), { ...r }));
    const roots: Record<string, any>[] = [];
    nodes.forEach((node) => {
        const pid = node[pk];
        const parent = pid == null ? undefined : nodes.get(pid);
        if (parent && parent !== node) {
            (parent[props.childrenField] ||= []).push(node);
        } else {
            roots.push(node);
        }
    });
    return roots;
}

function sourceRows(): Record<string, any>[] {
    return props.parentField ? toTree(props.rows) : props.rows;
}

/** Tabulator mutates its data, so hand it a copy and keep the parent's rows untouched. */
function cloneRows(rows: Record<string, any>[]): Record<string, any>[] {
    return rows.map((r) => {
        const copy: Record<string, any> = { ...r };
        const kids = r[props.childrenField];
        if (Array.isArray(kids)) copy[props.childrenField] = cloneRows(kids);
        return copy;
    });
}

/* ---------- Selection sync ---------- */

function applySelection() {
    if (!table || !built) return;
    const wanted = new Set(props.selectedIds);
    const current = table.getSelectedData().map(idOf);
    selectedCount.value = current.length;
    /* Already in sync (the usual case right after the user ticks a box): do nothing */
    if (current.length === wanted.size && current.every((k) => wanted.has(k))) return;

    syncingSelection = true;
    try {
        table.deselectRow();
        /* table.selectRow(keys) only finds top-level rows, so resolve nested rows by walking the tree */
        const found: RowComponent[] = [];
        walk(table.getRows(), (r) => {
            if (wanted.has(idOf(r.getData()))) found.push(r);
        });
        if (found.length) table.selectRow(found as any);
        selectedCount.value = table.getSelectedData().length;
    } finally {
        syncingSelection = false;
    }
}


/* ---------- Group bars (folders) ---------- */

type GroupEl = HTMLElement & { __fuGroupId?: TreeTableId };

/** The built-in "+" and "..." controls for a group bar. */
function groupControls(key: TreeTableId, meta: TreeTableGroup): VNode[] {
    const out: VNode[] = [];
    if (props.groupAdd) {
        out.push(
            h(FusionActionButton, {
                icon: Plus,
                size: "sm",
                variant: "ghost",
                ariaLabel: props.groupAddLabel,
                onClick: () => emit("add-task", { groupId: key }),
            }),
        );
    }
    const hidden: string[] = meta.hiddenActions ?? [];
    const list = (props.groupActions ?? []).filter((a) => !hidden.includes(a.key));
    if (list.length) {
        const actions = list.flatMap((a) => [
            ...(a.dividerBefore ? [{ type: "divider" as const }] : []),
            {
                label: a.label,
                icon: a.icon,
                disabled: a.disabled,
                onClick: () => emit("group-action", { groupId: key, action: a.key }),
            },
        ]);
        out.push(
            h(
                DropdownMenu,
                { actions, align: "left" },
                {
                    trigger: () =>
                        h(FusionActionButton, { icon: Ellipsis, size: "sm", variant: "ghost", ariaLabel: "Actions" }),
                },
            ),
        );
    }
    return out;
}

function groupHeader(key: TreeTableId, count: number, group: GroupComponent): HTMLElement {
    const wrap = document.createElement("div") as GroupEl;
    wrap.className = "fu-treetable__group";
    wrap.__fuGroupId = key;
    /* Buttons inside the bar (add, menu) must not open or close the group */
    wrap.addEventListener("click", (e) => {
        if ((e.target as HTMLElement).closest("button, a, input, select, textarea")) e.stopPropagation();
    });
    const meta = props.groups?.find((g) => g.id === key) ?? { id: key, label: String(key) };
    const open = group.getElement().classList.contains("tabulator-group-visible");
    const slot = (slots as Record<string, any>).group;
    const content = slot
        ? slot({ group: meta, count, open })
        : [
              h("span", { class: "fu-treetable__group-chevron", innerHTML: CHEVRON_SVG, "aria-hidden": "true" }),
              h("span", { class: "fu-treetable__group-name" }, meta.label),
              h("span", { class: "fu-treetable__group-count" }, String(count)),
              ...groupControls(key, meta),
          ];
    const vnode: VNode = h("div", { class: "fu-treetable__group-inner" }, content);
    if (instance) vnode.appContext = instance.appContext;
    render(vnode, wrap);
    mounted.add(wrap);
    return wrap;
}

function groupOfRow(row: RowComponent): TreeTableId | null {
    if (!props.groupField) return null;
    let root: RowComponent = row;
    let p = root.getTreeParent();
    while (p) {
        root = p;
        p = root.getTreeParent();
    }
    return root.getData()[props.groupField] ?? null;
}

/* ---------- Highlight the task that was just moved ---------- */

let movedKey: TreeTableId | null = null;
let movedTimer: ReturnType<typeof setTimeout> | null = null;

function flashMoved(key: TreeTableId) {
    movedKey = key;
    if (movedTimer) clearTimeout(movedTimer);
    movedTimer = setTimeout(() => {
        movedKey = null;
        host.value?.querySelectorAll(".is-moved").forEach((n) => n.classList.remove("is-moved"));
    }, 2000);
}

function applyMovedHighlight() {
    if (movedKey === null || !table) return;
    host.value?.querySelectorAll(".is-moved").forEach((n) => n.classList.remove("is-moved"));
    let hit: RowComponent | null = null;
    walk(table.getRows(), (r) => {
        if (idOf(r.getData()) === movedKey) hit = r;
    });
    if (!hit) return;
    const found: RowComponent = hit;
    found.getElement().classList.add("is-moved");
    /* Make sure the moved task is on screen, without jumping if it already is */
    found.scrollTo("nearest", false).catch(() => {});
}

/* ---------- Drag and drop (reorder and nest) ---------- */

const CHEVRON_SVG =
    '<svg viewBox="0 0 16 16" width="14" height="14"><path d="M6 3.5 10.5 8 6 12.5" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';

const GRIP_SVG =
    '<svg viewBox="0 0 16 16" width="14" height="14" aria-hidden="true"><g fill="currentColor"><circle cx="5.5" cy="3.5" r="1.2"/><circle cx="10.5" cy="3.5" r="1.2"/><circle cx="5.5" cy="8" r="1.2"/><circle cx="10.5" cy="8" r="1.2"/><circle cx="5.5" cy="12.5" r="1.2"/><circle cx="10.5" cy="12.5" r="1.2"/></g></svg>';

type RowEl = HTMLElement & { __fuRow?: RowComponent };

function decorateRow(row: RowComponent) {
    const el = row.getElement() as RowEl;
    el.__fuRow = row;
    el.classList.toggle("is-moved", movedKey !== null && idOf(row.getData()) === movedKey);
    if (!props.draggableRows) return;
    const header = el.querySelector(".tabulator-row-header");
    if (header && !header.querySelector(".fu-treetable__grip")) {
        const grip = document.createElement("span");
        grip.className = "fu-treetable__grip";
        grip.setAttribute("role", "button");
        grip.setAttribute("aria-label", "Drag to move task");
        grip.innerHTML = GRIP_SVG;
        header.insertBefore(grip, header.firstChild);
    }
}

let dragRow: RowComponent | null = null;
let dropTarget:
    | { kind: "row"; el: RowEl; row: RowComponent; position: TreeTableDropPosition }
    | { kind: "group"; el: HTMLElement; groupId: TreeTableId }
    | null = null;

function clearDropClasses() {
    host.value?.querySelectorAll(".is-drop-inside, .is-line-top, .is-line-bottom, .is-dragging").forEach((n) => {
        n.classList.remove("is-drop-inside", "is-line-top", "is-line-bottom", "is-dragging");
        (n as HTMLElement).style.removeProperty("--fu-tt-line-x");
    });
}

function isInside(candidate: RowComponent, ancestor: RowComponent): boolean {
    let p: RowComponent | false = candidate;
    const id = idOf(ancestor.getData());
    while (p) {
        if (idOf(p.getData()) === id) return true;
        p = p.getTreeParent();
    }
    return false;
}

function onGripDown(e: MouseEvent) {
    const grip = (e.target as HTMLElement).closest(".fu-treetable__grip");
    const rowEl = (e.target as HTMLElement).closest(".tabulator-row") as RowEl | null;
    if (grip && rowEl) rowEl.draggable = true;
}

function onGripUp() {
    host.value?.querySelectorAll<HTMLElement>(".tabulator-row[draggable=true]").forEach((r) => (r.draggable = false));
}

function onDragStart(e: DragEvent) {
    const rowEl = (e.target as HTMLElement).closest?.(".tabulator-row") as RowEl | null;
    if (!rowEl?.__fuRow || !rowEl.draggable) return;
    dragRow = rowEl.__fuRow;
    rowEl.classList.add("is-dragging");
    if (e.dataTransfer) {
        e.dataTransfer.effectAllowed = "move";
        e.dataTransfer.setData("text/plain", String(idOf(dragRow.getData())));
    }
}

function onDragOver(e: DragEvent) {
    if (!dragRow) return;
    const rowEl = (e.target as HTMLElement).closest?.(".tabulator-row") as RowEl | null;
    clearDropClasses();
    host.value?.querySelectorAll(".tabulator-row").forEach((n) => {
        if ((n as RowEl).__fuRow === dragRow) n.classList.add("is-dragging");
    });
    dropTarget = null;

    /* A group bar: dropping here puts the task first in that group */
    const groupEl = (e.target as HTMLElement).closest?.(".tabulator-group") as HTMLElement | null;
    if (groupEl) {
        const key = (groupEl.querySelector(".fu-treetable__group") as GroupEl | null)?.__fuGroupId;
        if (key !== undefined) {
            groupEl.classList.add("is-drop-inside");
            dropTarget = { kind: "group", el: groupEl, groupId: key };
            e.preventDefault();
            if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
        }
        return;
    }

    if (!rowEl?.__fuRow) return;

    const hovered = rowEl.__fuRow;
    const rect = rowEl.getBoundingClientRect();
    const ratio = (e.clientY - rect.top) / rect.height;
    const zone: TreeTableDropPosition = ratio < 0.28 ? "before" : ratio > 0.72 ? "after" : "inside";

    let target = hovered;
    let position: TreeTableDropPosition = zone;
    let lineLevel = levelOf(hovered);
    let edge: "top" | "bottom" = zone === "before" ? "top" : "bottom";

    if (zone === "after") {
        const kids = hovered.getTreeChildren();
        if (kids.length && hovered.isTreeExpanded()) {
            /* Under an open parent means "first child", not "after the whole group" */
            target = kids[0];
            position = "before";
            lineLevel = levelOf(hovered) + 1;
        } else {
            /* Drag left to pull the task out to a higher level (as long as nothing follows it at that level) */
            const cell = rowEl.querySelector<HTMLElement>(`[tabulator-field="${treeKey.value}"]`);
            if (cell) {
                const cellRect = cell.getBoundingClientRect();
                const pad = parseFloat(getComputedStyle(cell).paddingLeft) || 0;
                const wanted = Math.max(0, Math.round((e.clientX - (cellRect.left + pad)) / props.indent));
                let cur = hovered;
                let curLevel = lineLevel;
                while (curLevel > wanted && !hasNextSibling(cur)) {
                    const up = cur.getTreeParent();
                    if (!up) break;
                    cur = up;
                    curLevel--;
                }
                target = cur;
                lineLevel = curLevel;
            }
        }
    }

    if (isInside(target, dragRow)) return;

    if (position === "inside") {
        rowEl.classList.add("is-drop-inside");
    } else {
        const cell = rowEl.querySelector<HTMLElement>(`[tabulator-field="${treeKey.value}"]`);
        const pad = cell ? parseFloat(getComputedStyle(cell).paddingLeft) || 0 : 0;
        const x = cell ? cell.getBoundingClientRect().left - rect.left + pad + lineLevel * props.indent : 0;
        rowEl.style.setProperty("--fu-tt-line-x", `${x}px`);
        rowEl.classList.add(edge === "top" ? "is-line-top" : "is-line-bottom");
    }
    dropTarget = { kind: "row", el: rowEl, row: target, position };
    e.preventDefault();
    if (e.dataTransfer) e.dataTransfer.dropEffect = "move";
}

/**
 * After a drop the rows change under a pointer that has not moved, and the browser keeps the old :hover
 * on whatever row now sits there. Hide hover styling until the pointer actually moves again.
 */
function settleHover() {
    const el = host.value;
    if (!el) return;
    el.classList.add("is-settling");
    const clear = () => {
        el.classList.remove("is-settling");
        window.removeEventListener("pointermove", clear);
        window.removeEventListener("pointerdown", clear);
    };
    window.addEventListener("pointermove", clear, { once: true });
    window.addEventListener("pointerdown", clear, { once: true });
}

function onDrop(e: DragEvent) {
    if (!dragRow || !dropTarget) return;
    e.preventDefault();
    const source = dragRow;
    const fromParent = source.getTreeParent();
    flashMoved(idOf(source.getData()));
    settleHover();
    if (dropTarget.kind === "group") {
        emit("row-move", {
            id: idOf(source.getData()),
            targetId: null,
            position: "inside",
            fromParentId: fromParent ? idOf(fromParent.getData()) : null,
            toParentId: null,
            toGroupId: dropTarget.groupId,
        });
        onDragEnd();
        return;
    }
    const { row: target, position } = dropTarget;
    const toParent = position === "inside" ? target : target.getTreeParent();
    emit("row-move", {
        id: idOf(source.getData()),
        targetId: idOf(target.getData()),
        position,
        fromParentId: fromParent ? idOf(fromParent.getData()) : null,
        toParentId: toParent ? idOf(toParent.getData()) : null,
        ...(props.groupField ? { toGroupId: groupOfRow(target) } : {}),
    });
    /* The dragged row may already be gone when `dragend` fires, so reset here too */
    onDragEnd();
}

function onDragEnd() {
    dragRow = null;
    dropTarget = null;
    clearDropClasses();
    onGripUp();
}

function bindDnd() {
    const el = host.value;
    if (!el) return;
    el.addEventListener("mousedown", onGripDown);
    el.addEventListener("mouseup", onGripUp);
    el.addEventListener("dragstart", onDragStart);
    el.addEventListener("dragover", onDragOver);
    el.addEventListener("drop", onDrop);
    el.addEventListener("dragend", onDragEnd);
}

function unbindDnd() {
    const el = host.value;
    if (!el) return;
    el.removeEventListener("mousedown", onGripDown);
    el.removeEventListener("mouseup", onGripUp);
    el.removeEventListener("dragstart", onDragStart);
    el.removeEventListener("dragover", onDragOver);
    el.removeEventListener("drop", onDrop);
    el.removeEventListener("dragend", onDragEnd);
}

/* ---------- Table lifecycle ---------- */

function create() {
    if (!host.value) return;
    table = new Tabulator(host.value, {
        data: cloneRows(sourceRows()),
        index: props.idField,
        columns: buildColumns(),
        layout: "fitColumns",
        height: props.height ?? false,
        placeholder: props.emptyText,
        movableColumns: props.movableColumns,
        resizableColumnFit: true,
        selectableRows: props.selectable ? "highlight" : false,
        rowHeader: props.selectable
            ? {
                  formatter: "rowSelection",
                  titleFormatter: "rowSelection",
                  headerSort: false,
                  resizable: false,
                  frozen: true,
                  width: props.draggableRows ? 52 : 40,
                  minWidth: props.draggableRows ? 52 : 40,
                  hozAlign: "center",
                  headerHozAlign: "center",
              }
            : undefined,
        rowFormatter: (row: RowComponent) => decorateRow(row),
        ...(props.groupField
            ? {
                  groupBy: props.groupField,
                  groupValues: props.groups ? [props.groups.map((g) => g.id)] : undefined,
                  groupStartOpen: props.groupStartOpen,
                  groupToggleElement: "header" as const,
                  /* Tabulator accepts a DOM element here even though its types say string */
                  groupHeader: ((value: any, count: number, _data: any, group: GroupComponent) =>
                      groupHeader(value, count, group)) as any,
              }
            : {}),
        dataTree: true,
        dataTreeChildField: props.childrenField,
        dataTreeElementColumn: treeKey.value,
        dataTreeStartExpanded: props.startExpanded,
        dataTreeChildIndent: props.indent,
        dataTreeBranchElement: '<span class="fu-treetable__branch"></span>',
        dataTreeSelectPropagate: props.propagateSelection,
        dataTreeExpandElement: chevron(false),
        dataTreeCollapseElement: chevron(true),
        headerSortElement: '<span class="fu-treetable__sort"></span>',
    });

    table.on("tableBuilt", () => {
        built = true;
        holderEl = host.value?.querySelector<HTMLElement>(".tabulator-tableholder") ?? null;
        /* The library's thin scrollbar for the table's own scrolling (sideways, and up and down with a fixed height) */
        holderEl?.classList.add("customScrollBar");
        holderEl?.addEventListener("scroll", onHolderScroll, { passive: true });
        applySelection();
    });
    table.on("renderComplete", pruneDetached);
    table.on("dataSorted", () => nextTick(refreshGuides));
    table.on("rowClick", (e: UIEvent, row: RowComponent) => {
        const target = e.target as HTMLElement;
        if (target.closest(".fu-treetable__chevron, input[type=checkbox], button, a, input, select, textarea")) return;
        emit("row-click", row.getData());
    });
    table.on("rowSelectionChanged", (data: any[]) => {
        selectedCount.value = data.length;
        if (syncingSelection) return;
        emit("update:selectedIds", data.map(idOf));
    });
    watchColumnDrag();
    table.on("columnMoved", (_col, cols) => {
        emit(
            "columns-reordered",
            cols.map((c) => c.getField()).filter((f): f is string => !!f),
        );
    });
    table.on("columnResized", (col) => {
        const key = col.getField();
        if (key) emit("column-resized", { key, width: col.getWidth() });
    });
    table.on("dataSorted", (sorters) => {
        const s = sorters[0];
        emit("sort-change", s ? { key: s.field, dir: s.dir as "asc" | "desc" } : null);
    });
    table.on("dataTreeRowExpanded", (row) => emit("row-expanded", row.getData()));
    table.on("dataTreeRowCollapsed", (row) => emit("row-collapsed", row.getData()));
}

onMounted(() => {
    create();
    bindDnd();
});

/*
 * While a column header is dragged, shade the whole column so you can see it travelling. Tabulator
 * moves the column's cells live but only fires an event once you drop, so this watches for the
 * floating copy of the header it adds (".tabulator-moving") and marks that column's cells.
 */
let dragObserver: MutationObserver | null = null;
let shaded: HTMLElement[] = [];

function markColumn(field: string | null) {
    shaded.forEach((el) => el.classList.remove("fu-treetable__col-dragging"));
    shaded = [];
    if (!field || !table) return;
    // Cells carry no field name in the DOM, so ask Tabulator for the column's cells
    table
        .getColumn(field)
        ?.getCells()
        .forEach((c) => {
            const el = c.getElement();
            el.classList.add("fu-treetable__col-dragging");
            shaded.push(el);
        });
}

function watchColumnDrag() {
    if (!host.value || dragObserver) return;
    dragObserver = new MutationObserver((records) => {
        for (const r of records) {
            r.addedNodes.forEach((n) => {
                if (n instanceof HTMLElement && n.classList.contains("tabulator-moving")) markColumn(n.getAttribute("tabulator-field"));
            });
            r.removedNodes.forEach((n) => {
                if (n instanceof HTMLElement && n.classList.contains("tabulator-moving")) markColumn(null);
            });
        }
    });
    dragObserver.observe(host.value, { childList: true, subtree: true });
}

onBeforeUnmount(() => {
    dragObserver?.disconnect();
    dragObserver = null;
    if (movedTimer) clearTimeout(movedTimer);
    unbindDnd();
    holderEl?.removeEventListener("scroll", onHolderScroll);
    mounted.forEach((el) => render(null, el));
    mounted.clear();
    table?.destroy();
    table = null;
    built = false;
});

/* Data changes. */
watch(
    () => props.rows,
    async () => {
        if (!table || !built) return;
        await table.replaceData(cloneRows(sourceRows()));
        applySelection();
        await nextTick();
        applyMovedHighlight();
    },
    { deep: true },
);

/* Column changes (label, width, visibility, order coming from the parent). */
const columnSignature = computed(() =>
    JSON.stringify(visibleColumns.value.map((c) => [c.key, c.label, c.width, c.sortable, c.resizable, c.textAlign])),
);
watch(columnSignature, async () => {
    if (!table || !built) return;
    table.setColumns(buildColumns());
    await nextTick();
    applySelection();
});

watch(
    () => props.selectedIds,
    () => applySelection(),
    { deep: true },
);

watch(
    () => props.height,
    (h) => table?.setHeight(h ?? ("" as any)),
);

watch(
    () => props.loading,
    async (v) => {
        if (v) return;
        await nextTick();
        table?.redraw(true);
    },
);

/* Skeleton: same widths and shimmer as FusionListView */
const widthSets = [
    ["55%", "70%", "40%", "65%", "50%"],
    ["75%", "45%", "80%", "55%", "60%"],
    ["60%", "80%", "50%", "70%", "45%"],
    ["45%", "65%", "75%", "40%", "70%"],
    ["70%", "50%", "60%", "80%", "55%"],
];
function skeletonWidth(rowIndex: number, colIndex: number): string {
    return widthSets[(rowIndex - 1) % widthSets.length][colIndex % 5];
}
const skeletonGrid = computed(() => {
    const lead = props.selectable ? (props.draggableRows ? 52 : 40) : 0;
    const cols = visibleColumns.value.map((c) => (c.width ? `${c.width}px` : "minmax(0, 1fr)"));
    return [lead ? `${lead}px` : "", ...cols].filter(Boolean).join(" ");
});

/* ---------- Public API ---------- */

function walk(rows: RowComponent[], fn: (r: RowComponent) => void) {
    rows.forEach((r) => {
        fn(r);
        walk(r.getTreeChildren(), fn);
    });
}

defineExpose({
    expandAll() {
        table && walk(table.getRows(), (r) => r.getTreeChildren().length && r.treeExpand());
    },
    collapseAll() {
        table && walk(table.getRows(), (r) => r.getTreeChildren().length && r.treeCollapse());
    },
    clearSelection() {
        emit("update:selectedIds", []);
    },
    redraw(force = true) {
        table?.redraw(force);
    },
    getTable: () => table,
});
</script>

<template>
    <div class="fu-treetable" :class="{ 'is-loading': loading, 'has-selection': selectedCount > 0, 'is-scrolled': scrolled, 'is-sticky-header': stickyHeader }" :style="stickyHeader ? { '--fu-tt-sticky-top': stickyOffset + 'px' } : undefined">
        <div v-show="!loading" ref="host" class="fu-treetable__host" />
        <!-- Whatever you put in the footer slot sits under the last row, at the bottom left (for example an "Add folder" button) -->
        <div v-if="$slots.footer && !loading" class="fu-treetable__footer">
            <slot name="footer" />
        </div>
        <div v-if="loading" class="fu-treetable__skeleton" aria-busy="true" aria-live="polite">
            <div class="fu-treetable__skeleton-row fu-treetable__skeleton-row--head" :style="{ gridTemplateColumns: skeletonGrid }">
                <div v-if="selectable" class="fu-treetable__skeleton-cell fu-treetable__skeleton-cell--checkbox" />
                <div v-for="col in visibleColumns" :key="col.key">
                    <div class="fu-treetable__skeleton-cell fu-treetable__skeleton-cell--header" />
                </div>
            </div>
            <div
                v-for="i in skeletonRows"
                :key="i"
                class="fu-treetable__skeleton-row"
                :style="{ gridTemplateColumns: skeletonGrid }"
            >
                <div v-if="selectable" class="fu-treetable__skeleton-cell fu-treetable__skeleton-cell--checkbox" />
                <div v-for="(col, ci) in visibleColumns" :key="col.key">
                    <div class="fu-treetable__skeleton-cell" :style="{ width: skeletonWidth(i, ci) }" />
                </div>
            </div>
        </div>
    </div>
</template>
