<script setup lang="ts">
/**
 * FusionVersionList
 * The history of what was sent to a client. Newest first. Each version opens to show what was sent,
 * the email, and what the client said about it.
 */
import { computed, ref } from "vue";
import { ChevronRight } from "@lucide/vue";

export type VersionTone = "neutral" | "info" | "success" | "warning" | "danger";

export interface VersionSentItem {
    /** The task or subtask. */
    name: string;
    /** What was shown, for example "Figma frames". */
    type: string;
    /** For example "2 frames". */
    count: string;
}

export interface VersionFeedback {
    text: string;
    /** For example "Fixed in v3", "To fix", "Approved". */
    state: string;
    tone?: VersionTone;
}

export interface VersionItem {
    id: string | number;
    /** "v2" */
    label: string;
    /** For example "Sent 10 Nov by Faris Ansari". */
    sentText: string;
    /** One line under the title, for example "4 frames · 2 updated". */
    summary?: string;
    /** Small grey tag next to the label, for example "Latest sent". */
    tag?: string;
    /** The client's answer for this version. */
    answer?: { text: string; tone?: VersionTone };
    sent?: VersionSentItem[];
    email?: { subject: string };
    feedback?: VersionFeedback[];
    /** Text for the empty feedback line, for example "Waiting for the client." */
    feedbackEmpty?: string;
    /** Label of the compare link, for example "Compare with v1". Hidden when empty. */
    compareLabel?: string;
}

const props = withDefaults(
    defineProps<{
        versions: VersionItem[];
        /** Ids of open versions (v-model:open). When omitted the list manages it and opens the first one. */
        open?: (string | number)[];
        /** Open every version to start. */
        startAllOpen?: boolean;
        emptyText?: string;
    }>(),
    { startAllOpen: false, emptyText: "Not sent yet. The first send creates v1." },
);

const emit = defineEmits<{
    (e: "update:open", ids: (string | number)[]): void;
    (e: "compare", id: string | number): void;
    (e: "open-email", id: string | number): void;
}>();

const inner = ref<(string | number)[]>(
    props.startAllOpen ? props.versions.map((v) => v.id) : props.versions[0] ? [props.versions[0].id] : [],
);
const openIds = computed(() => props.open ?? inner.value);

function toggle(id: string | number) {
    const next = openIds.value.includes(id) ? openIds.value.filter((i) => i !== id) : [...openIds.value, id];
    inner.value = next;
    emit("update:open", next);
}
</script>

<template>
    <div class="fu-versions">
        <p v-if="!versions.length" class="fu-versions__empty">{{ emptyText }}</p>

        <div v-for="v in versions" :key="v.id" class="fu-versions__item">
            <div class="fu-versions__head">
                <button
                    type="button"
                    class="fu-versions__toggle"
                    :aria-expanded="openIds.includes(v.id)"
                    @click="toggle(v.id)"
                >
                    <ChevronRight :size="14" class="fu-versions__chev" :class="{ 'is-open': openIds.includes(v.id) }" />
                    <span class="fu-versions__titles">
                        <span class="fu-versions__line">
                            <b class="fu-versions__label">{{ v.label }}</b>
                            <span v-if="v.tag" class="fu-versions__tag">{{ v.tag }}</span>
                            <span class="fu-versions__sent">{{ v.sentText }}</span>
                        </span>
                        <span v-if="v.summary" class="fu-versions__summary">{{ v.summary }}</span>
                    </span>
                </button>

                <div class="fu-versions__side">
                    <span v-if="v.answer" class="fu-versions__pill" :class="`is-${v.answer.tone || 'neutral'}`">{{
                        v.answer.text
                    }}</span>
                    <button v-if="v.compareLabel" type="button" class="fu-versions__link" @click="emit('compare', v.id)">
                        {{ v.compareLabel }}
                    </button>
                </div>
            </div>

            <div v-if="openIds.includes(v.id)" class="fu-versions__body">
                <slot name="body" :version="v">
                    <span class="fu-versions__key">Sent</span>
                    <div class="fu-versions__col">
                        <div v-for="s in v.sent || []" :key="s.name" class="fu-versions__sentrow">
                            <span class="fu-versions__grow">{{ s.name }}</span>
                            <span class="fu-versions__muted">{{ s.type }} · {{ s.count }}</span>
                        </div>
                        <span v-if="!v.sent?.length" class="fu-versions__muted">Nothing recorded.</span>
                    </div>

                    <template v-if="v.email">
                        <span class="fu-versions__key">Email</span>
                        <div class="fu-versions__sentrow">
                            <span class="fu-versions__grow">{{ v.email.subject }}</span>
                            <button type="button" class="fu-versions__link" @click="emit('open-email', v.id)">Open</button>
                        </div>
                    </template>

                    <span class="fu-versions__key">Client said</span>
                    <div class="fu-versions__col">
                        <div v-for="f in v.feedback || []" :key="f.text" class="fu-versions__sentrow">
                            <span class="fu-versions__grow">{{ f.text }}</span>
                            <span class="fu-versions__pill fu-versions__pill--sm" :class="`is-${f.tone || 'neutral'}`">{{
                                f.state
                            }}</span>
                        </div>
                        <span v-if="!v.feedback?.length" class="fu-versions__muted">{{
                            v.feedbackEmpty || "No comments."
                        }}</span>
                    </div>
                </slot>
            </div>
        </div>
    </div>
</template>

