export type TreeTableDropPosition = "before" | "after" | "inside";

export type TreeTableId = string | number;

/**
 * What the table reports when a task is dropped. The hierarchy is:
 *   group  ->  top level task (has `group_id`, no parent)  ->  subtask (has `parent_id`, no group)
 */
export interface TreeTableMove {
    /** The task that was dragged. */
    id: TreeTableId;
    /** The task it was dropped on. null when dropped on a group bar. */
    targetId: TreeTableId | null;
    position: TreeTableDropPosition;
    /** Parent before the move (null = it was a top level task). */
    fromParentId: TreeTableId | null;
    /** Parent after the move (null = it is now a top level task). */
    toParentId: TreeTableId | null;
    /** Group after the move. Only when the table is grouped. Dropping on a group bar puts the task first in that group. */
    toGroupId?: TreeTableId | null;
}

type Row = Record<string, any>;
type MoveInput = Pick<TreeTableMove, "id" | "targetId" | "position"> & { toGroupId?: TreeTableId | null };

/**
 * Nested rows (`children` arrays). Returns a new array. Does not mutate the input.
 * Only top level tasks carry the group id; a task moved inside another loses it.
 * Returns the original rows if the move is not allowed (onto itself, or into its own subtasks).
 */
export function moveTreeRow(
    rows: Row[],
    move: MoveInput,
    opts: { idField?: string; childrenField?: string; groupField?: string } = {},
): Row[] {
    const idField = opts.idField ?? "id";
    const childrenField = opts.childrenField ?? "children";
    const { groupField } = opts;

    const clone = (list: Row[]): Row[] =>
        list.map((r) => {
            const c: Row = { ...r };
            if (Array.isArray(r[childrenField])) c[childrenField] = clone(r[childrenField]);
            return c;
        });
    const tree = clone(rows);

    const find = (list: Row[], id: TreeTableId): { list: Row[]; index: number } | null => {
        for (let i = 0; i < list.length; i++) {
            if (list[i][idField] === id) return { list, index: i };
            const kids = list[i][childrenField];
            if (Array.isArray(kids)) {
                const hit = find(kids, id);
                if (hit) return hit;
            }
        }
        return null;
    };

    const source = find(tree, move.id);
    if (!source || move.id === move.targetId) return rows;
    const node = source.list[source.index];

    if (move.targetId !== null && Array.isArray(node[childrenField]) && find(node[childrenField], move.targetId)) return rows;

    source.list.splice(source.index, 1);

    /* Dropped on a group bar: first task of that group */
    if (move.targetId === null) {
        if (!groupField || move.toGroupId == null) return rows;
        node[groupField] = move.toGroupId;
        const firstAt = tree.findIndex((r) => r[groupField] === move.toGroupId);
        if (firstAt === -1) tree.push(node);
        else tree.splice(firstAt, 0, node);
        return tree;
    }

    const target = find(tree, move.targetId);
    if (!target) return rows;

    if (move.position === "inside") {
        const t = target.list[target.index];
        if (!Array.isArray(t[childrenField])) t[childrenField] = [];
        t[childrenField].push(node);
        if (groupField) delete node[groupField];
    } else {
        const at = move.position === "before" ? target.index : target.index + 1;
        target.list.splice(at, 0, node);
        if (groupField) {
            if (target.list === tree) {
                /* The moved task sits next to `target`, so it takes target's group */
                const next = tree[at === target.index ? at + 1 : target.index];
                node[groupField] = next[groupField];
            } else {
                delete node[groupField];
            }
        }
    }
    return tree;
}

/**
 * Flat rows, shaped like a database table:
 *   top level task:  { id, group_id: 3, parent_id: null }
 *   subtask:         { id, group_id: null, parent_id: 12 }
 * Pair it with the table's `parentField` and `groupField` props. Returns a new array: only the moved
 * task changes (its `parent_id` / `group_id`), plus the array order, which is the order of siblings.
 * Returns the original rows if the move is not allowed.
 */
export function moveFlatRow(
    rows: Row[],
    move: MoveInput,
    opts: { idField?: string; parentField: string; groupField?: string },
): Row[] {
    const idField = opts.idField ?? "id";
    const { parentField, groupField } = opts;
    const byId = new Map(rows.map((r) => [r[idField], r]));
    const node = byId.get(move.id);
    if (!node || move.id === move.targetId) return rows;

    /* Not into itself or one of its own subtasks */
    if (move.targetId !== null) {
        let cur: Row | undefined = byId.get(move.targetId);
        while (cur) {
            if (cur[idField] === move.id) return rows;
            const pid = cur[parentField];
            cur = pid == null ? undefined : byId.get(pid);
        }
    }

    /* The group of a task is the group of its top level ancestor */
    const groupOf = (r: Row): TreeTableId | null => {
        let cur: Row | undefined = r;
        while (cur && cur[parentField] != null) cur = byId.get(cur[parentField]);
        return groupField && cur ? (cur[groupField] ?? null) : null;
    };

    const rest = rows.filter((r) => r !== node);
    let parent: TreeTableId | null = null;
    let group: TreeTableId | null = null;
    let at = rest.length;

    if (move.targetId === null) {
        /* Dropped on a group bar: first top level task of that group */
        if (!groupField || move.toGroupId == null) return rows;
        group = move.toGroupId;
        const first = rest.findIndex((r) => r[parentField] == null && r[groupField] === group);
        at = first === -1 ? rest.length : first;
    } else {
        const ti = rest.findIndex((r) => r[idField] === move.targetId);
        if (ti === -1) return rows;
        const target = rest[ti];
        if (move.position === "inside") {
            parent = target[idField];
            let last = ti;
            rest.forEach((r, i) => {
                if (r[parentField] === parent) last = i;
            });
            at = last + 1;
        } else {
            parent = target[parentField] ?? null;
            at = move.position === "before" ? ti : ti + 1;
            if (parent === null) group = groupOf(target);
        }
    }

    /* Top level: group_id set, no parent. Subtask: parent set, no group. */
    const moved: Row = { ...node, [parentField]: parent };
    if (groupField) moved[groupField] = parent === null ? group : null;
    const out = rest.slice();
    out.splice(at, 0, moved);
    return out;
}
