<template>
  <div
    class="fu-segmented"
    :class="[`fu-segmented--${size}`, { 'fu-segmented--block': block }]"
    role="radiogroup"
    :aria-label="ariaLabel"
    @keydown="onKeydown"
  >
    <button
      v-for="(option, i) in options"
      :key="option.value"
      :ref="(el) => (itemRefs[i] = el as HTMLElement | null)"
      type="button"
      role="radio"
      class="fu-segmented__option"
      :class="{ 'is-active': option.value === modelValue }"
      :aria-checked="option.value === modelValue"
      :tabindex="isTabStop(i) ? 0 : -1"
      :disabled="disabled || option.disabled"
      @click="select(option)"
    >
      <component :is="option.icon" v-if="option.icon" :size="16" :stroke-width="2" />
      <span>{{ option.label }}</span>
    </button>
  </div>
</template>

<script setup lang="ts">
import { computed, ref, type Component } from "vue";

export interface FuSegmentedOption {
  /** Value emitted through `update:modelValue` */
  value: string;
  label: string;
  /** Optional icon component shown before the label */
  icon?: Component;
  disabled?: boolean;
}

const props = withDefaults(
  defineProps<{
    /** Selected option value (use with `v-model`) */
    modelValue: string;
    options: FuSegmentedOption[];
    size?: "sm" | "md" | "lg";
    /** Stretches the control to the full width with equal segments */
    block?: boolean;
    disabled?: boolean;
    ariaLabel?: string;
  }>(),
  { size: "md", block: false, disabled: false }
);

const emit = defineEmits<{ (e: "update:modelValue", value: string): void }>();

const itemRefs = ref<(HTMLElement | null)[]>([]);

const activeIndex = computed(() => {
  const i = props.options.findIndex((o) => o.value === props.modelValue);
  return i === -1 ? props.options.findIndex((o) => !o.disabled) : i;
});

function isTabStop(i: number) {
  return i === activeIndex.value;
}

function select(option: FuSegmentedOption) {
  if (props.disabled || option.disabled || option.value === props.modelValue) return;
  emit("update:modelValue", option.value);
}

function onKeydown(event: KeyboardEvent) {
  const keys: Record<string, number> = { ArrowRight: 1, ArrowDown: 1, ArrowLeft: -1, ArrowUp: -1 };
  const step = keys[event.key];
  if (!step) return;

  const count = props.options.length;
  let next = activeIndex.value;
  for (let n = 0; n < count; n++) {
    next = (next + step + count) % count;
    if (!props.options[next].disabled) break;
  }

  event.preventDefault();
  select(props.options[next]);
  itemRefs.value[next]?.focus();
}
</script>

