<template>
  <div class="fu-tabs" :class="{ 'fu-tabs--plain': variant === 'plain' }">
    <!-- Tab Headers -->
    <div class="fu-tabs__header-wrapper">
      <div ref="tabsRow" class="fu-tabs-buttons scrollbar__control customScrollBar" :class="{ 'is-dragging': dragKey !== null }">
        <template v-for="tab in displayTabs" :key="tab.key">
          <!-- RENAMING (customizable tabs): the title becomes a field. Enter or clicking away saves, Esc cancels. -->
          <div v-if="renamingKey === tab.key" class="fu-tab fu-tab--active fu-tab--renaming">
            <input
              :ref="(el) => (renameInput = el)"
              v-model="renameDraft"
              class="fu-tab__rename"
              :aria-label="`Rename ${tab.title || tab.key}`"
              @keydown.enter.prevent="saveRename(tab)"
              @keydown.esc.prevent="renamingKey = null"
              @blur="saveRename(tab)"
            />
          </div>

          <div
            v-else
            class="fu-tab-item"
            :class="{
              'is-custom': customizable,
              'is-active': activeTab === tab.key,
              'is-menu-open': menuOpenKey === tab.key,
              'is-dragging': dragKey === tab.key,
            }"
            :data-tab-key="tab.key"
            @pointerdown="onDragStart($event, tab)"
          >
            <!-- The body is what lifts and follows the pointer; the item stays put and marks where it will land -->
            <div class="fu-tab-item__body" :style="dragKey === tab.key ? { transform: `translateX(${dragDx}px)` } : undefined">
            <button
              @click="onTabClick(tab.key)"
              class="fu-tab"
              :class="{ 'fu-tab--active': activeTab === tab.key }"
              :disabled="tab.disabled"
            >
              <!-- AVATAR -->
              <div v-if="tab.avatarSrc || tab.avatarText" class="fu-tab__avatar">
                <img
                  v-if="tab.avatarSrc"
                  :src="tab.avatarSrc"
                  class="fu-tab__avatar-img"
                  alt="avatar"
                />
                <div v-else class="fu-tab__avatar-fallback">
                  {{ tab.avatarText?.charAt(0)?.toUpperCase() }}
                </div>
              </div>

              <!-- ICON -->
              <component
                v-else-if="tab.icon"
                :is="tab.icon"
                :size="16"
                class="fu-tab__icon"
              />

              <!-- TITLE (a custom name from `labels` wins over the tab's own title) -->
              <span
                v-if="!tab.avatarSrc && !tab.avatarText && titleOf(tab)"
                class="fu-tab__title"
              >
                {{ titleOf(tab) }}
              </span>

              <!-- COUNT -->
              <span v-if="typeof tab.count === 'number'" class="fu-tab__count">
                {{ tab.count }}
              </span>
            </button>

            <!-- OPTIONS (customizable tabs): a ... that takes the icon's place when you point at the tab -->
            <DropdownMenu
              v-if="customizable"
              :actions="tabMenu(tab)"
              align="left"
              class="fu-tab__menu"
              @open="menuOpenKey = tab.key"
              @close="menuOpenKey = null"
            >
              <template #trigger>
                <FusionActionButton :icon="Ellipsis" size="sm" variant="ghost" :ariaLabel="`Options for ${titleOf(tab)}`" />
              </template>
            </DropdownMenu>
            </div>
          </div>
        </template>

        <!-- ADD (customizable tabs only): a + right after the last tab. It opens a list of the tabs that are
             not shown, with a preview of the one you point at and a button to add it. -->
        <span v-if="customizable && addableTabs.length" class="fu-tabs__add">
          <FusionPickerPopover
            :items="addItems"
            :heading="addHeading"
            :actionLabel="addActionLabel"
            @action="(item) => addTab(item.key)"
          >
            <template #trigger>
              <FusionActionButton :icon="Plus" size="sm" variant="ghost" :ariaLabel="addLabel" />
            </template>
          </FusionPickerPopover>
        </span>
      </div>
    </div>

    <!-- Tab Body -->
    <div class="fu-tabs__content-wrapper">
      <div class="fu-tabs__body scrollbar__control customScrollBar" ref="tabBody">
        <keep-alive>
          <div
            v-for="tab in visibleTabs"
            :key="tab.key"
            class="fu-tab-panel"
            v-show="activeTab === tab.key"
          >
            <slot :name="tab.key" />
          </div>
        </keep-alive>
      </div>

      <!-- Pinned under the body. Fill it with the footer slot, or from inside a tab with <FusionTabFooter tab="key"> -->
      <div class="fu-tabs__footer" ref="footerEl">
        <slot name="footer" />
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onBeforeUnmount, nextTick, provide, watch } from "vue";
import { ArrowLeft, ArrowRight, Ellipsis, Pencil, Plus, Star, X } from "@lucide/vue";
import DropdownMenu from "../dropdownMenu/DropdownMenu.vue";
import FusionPickerPopover from "../pickerPopover/FusionPickerPopover.vue";
import FusionActionButton from "../actionButton/FusionActionButton.vue";

const props = defineProps({
  tabs: Array,
  defaultActiveDesktop: String,
  defaultActiveMobile: String,
  /**
   * Let people choose which tabs show. A + at the end lists the tabs that are not shown (with their
   * `description` if the tab has one), and each shown tab gets a remove button. Off by default.
   */
  customizable: { type: Boolean, default: false },
  /** The keys of the tabs that show (v-model:visibleKeys). Left out, every tab shows. */
  visibleKeys: Array,
  /**
   * Custom names by tab key, for example { tasks: "To do" } (v-model:labels). The keys and `title`s stay
   * clean, so the names people chose can be saved on their own.
   */
  labels: Object,
  /** The key of the tab that opens first (v-model:defaultKey), set from each tab's menu. */
  defaultKey: String,
  /** Keys that always show and cannot be removed, for example the summary. */
  lockedKeys: { type: Array, default: () => [] },
  /**
   * "default" has the grey tab strip. "plain" has no background of its own, so the strip sits on the page
   * colour with just the line under it.
   */
  variant: { type: String, default: "default" },
  /** Accessible name of the + button. */
  addLabel: { type: String, default: "Add a tab" },
  /** Heading of the list the + opens. */
  addHeading: { type: String, default: "Views" },
  /** Label of the button that adds the tab you are pointing at. */
  addActionLabel: { type: String, default: "Add to navigation" },
});

const emit = defineEmits(["tab-change", "update:visibleKeys", "update:labels", "update:defaultKey"]);

const isMobile = ref(window.innerWidth <= 768);
const activeTab = ref("");
const tabBody = ref(null);

// Lets a tab put its own bar in the pinned footer (see FusionTabFooter)
const footerEl = ref(null);
provide("fuTabs", { activeTab, footerEl });

/* The keys that show when the tabs are customizable. Starts from the v-model, or from every tab. */
const shownKeys = ref(props.visibleKeys ?? props.tabs.map((t) => t.key));
watch(
  () => props.visibleKeys,
  (keys) => {
    if (keys) shownKeys.value = keys;
  },
);

const isLocked = (key) => props.lockedKeys.includes(key);
const isShown = (key) => !props.customizable || shownKeys.value.includes(key) || isLocked(key);

/* Custom names and the default tab are held here and reported through the v-models */
const customLabels = ref({ ...(props.labels ?? {}) });
watch(() => props.labels, (l) => (customLabels.value = { ...(l ?? {}) }));
const customDefault = ref(props.defaultKey ?? null);
watch(() => props.defaultKey, (k) => (customDefault.value = k ?? null));

const titleOf = (tab) => customLabels.value[tab.key] || tab.title || tab.key;

const visibleTabs = computed(() => {
  const list = props.tabs.filter((t) => (!t.mobileOnly || isMobile.value) && isShown(t.key));
  if (!props.customizable) return list;
  // The order is the order of the keys, so moving a tab left or right changes what is saved
  const at = (t) => shownKeys.value.indexOf(t.key);
  return [...list].sort((a, b) => at(a) - at(b));
});

/* While a tab is being dragged, the tabs show in the order the drag is heading for */
const dragKey = ref(null);
const dragDx = ref(0);
const dragOrder = ref(null);
const tabsRow = ref(null);

const displayTabs = computed(() => {
  if (!dragOrder.value) return visibleTabs.value;
  const byKey = new Map(visibleTabs.value.map((t) => [t.key, t]));
  return dragOrder.value.map((k) => byKey.get(k)).filter(Boolean);
});

const addableTabs = computed(() =>
  props.tabs.filter((t) => (!t.mobileOnly || isMobile.value) && !isShown(t.key))
);

/* What the + lists. A tab can carry a `description` and a `preview` picture for the right-hand side. */
const addItems = computed(() =>
  addableTabs.value.map((t) => ({
    key: t.key,
    label: t.title || t.key,
    icon: t.icon,
    description: t.description,
    image: t.preview,
  })),
);

function setShown(keys) {
  shownKeys.value = keys;
  emit("update:visibleKeys", keys);
}

const orderedKeys = () => visibleTabs.value.map((t) => t.key);

function addTab(key) {
  // A new tab goes at the end, after the last one, where the + is
  setShown([...orderedKeys(), key]);
  nextTick(() => setActive(key));
}

function removeTab(key) {
  if (isLocked(key)) return;
  const wasActive = activeTab.value === key;
  setShown(orderedKeys().filter((k) => k !== key));
  if (customDefault.value === key) setDefault(null);
  // Closing the tab you are on moves you to the first one that is left
  if (wasActive) nextTick(() => setActive(visibleTabs.value[0]?.key));
}

function moveTab(key, dir) {
  const keys = orderedKeys();
  const i = keys.indexOf(key);
  const j = i + dir;
  if (i < 0 || j < 0 || j >= keys.length) return;
  [keys[i], keys[j]] = [keys[j], keys[i]];
  setShown(keys);
}

function setDefault(key) {
  customDefault.value = key;
  emit("update:defaultKey", key);
}

/* ---- rename ---- */
const renamingKey = ref(null);
const renameDraft = ref("");
let renameInput = null;
async function startRename(tab) {
  renameDraft.value = titleOf(tab);
  renamingKey.value = tab.key;
  await nextTick();
  renameInput?.focus();
  renameInput?.select();
}
function saveRename(tab) {
  if (renamingKey.value !== tab.key) return;
  const name = renameDraft.value.trim();
  const next = { ...customLabels.value };
  // Back to the original name (or empty) drops the custom one
  if (name && name !== tab.title) next[tab.key] = name;
  else delete next[tab.key];
  customLabels.value = next;
  emit("update:labels", next);
  renamingKey.value = null;
}

/* ---- the ... menu on each tab ---- */
const menuOpenKey = ref(null);
function tabMenu(tab) {
  const keys = orderedKeys();
  const i = keys.indexOf(tab.key);
  const isDefault = (customDefault.value ?? props.defaultActiveDesktop ?? keys[0]) === tab.key;
  return [
    { label: isDefault ? "Default tab" : "Set as default", icon: Star, disabled: isDefault, onClick: () => setDefault(tab.key) },
    { label: "Rename", icon: Pencil, onClick: () => startRename(tab) },
    { type: "divider" },
    { label: "Move tab left", icon: ArrowLeft, disabled: i <= 0, onClick: () => moveTab(tab.key, -1) },
    { label: "Move tab right", icon: ArrowRight, disabled: i >= keys.length - 1, onClick: () => moveTab(tab.key, 1) },
    ...(isLocked(tab.key) ? [] : [{ type: "divider" }, { label: "Remove", icon: X, onClick: () => removeTab(tab.key) }]),
  ];
}

function wakeScroll() {
  const el = tabBody.value;
  if (!el) return;
  el.style.overflowY = "hidden";
  requestAnimationFrame(() => {
    el.style.overflowY = "auto";
  });
}

/* ---- drag a tab to a new place (mouse: drag; touch: press and hold, then drag) ---- */
let drag = null;
let suppressClick = false;
const blockScroll = (e) => {
  if (drag?.started) e.preventDefault();
};

function onDragStart(e, tab) {
  if (!props.customizable || renamingKey.value !== null) return;
  if (e.pointerType === "mouse" && e.button !== 0) return;
  // The ... is a button of its own
  if (e.target.closest?.(".fu-tab__menu")) return;
  drag = { key: tab.key, el: e.currentTarget, startX: e.clientX, started: false, touch: e.pointerType === "touch", timer: null, grabDx: 0 };
  // On touch, a short hold starts the drag, so a swipe along the tab row still scrolls it
  if (drag.touch) drag.timer = setTimeout(() => beginDrag(drag.startX), 280);
  window.addEventListener("pointermove", onDragMove);
  window.addEventListener("pointerup", onDragEnd);
  window.addEventListener("pointercancel", onDragEnd);
  window.addEventListener("touchmove", blockScroll, { passive: false });
}

function beginDrag(x) {
  if (!drag || drag.started) return;
  drag.started = true;
  drag.grabDx = x - drag.el.getBoundingClientRect().left;
  dragKey.value = drag.key;
  dragOrder.value = orderedKeys();
  dragDx.value = 0;
}

function onDragMove(e) {
  if (!drag) return;
  if (!drag.started) {
    const moved = Math.abs(e.clientX - drag.startX);
    if (drag.touch) {
      // Moving before the hold is up means they are scrolling the row, not dragging
      if (moved > 8) cleanupDrag();
      return;
    }
    if (moved < 6) return;
    beginDrag(drag.startX);
  }
  e.preventDefault();
  const row = tabsRow.value;
  if (!row) return;
  const pointer = e.clientX - row.getBoundingClientRect().left + row.scrollLeft;
  const el = drag.el;
  dragDx.value = pointer - drag.grabDx - el.offsetLeft;
  // The tab lands after every other tab whose middle is left of the dragged tab's middle
  const centre = pointer - drag.grabDx + el.offsetWidth / 2;
  const others = [...row.querySelectorAll(".fu-tab-item")].filter((i) => i.dataset.tabKey !== drag.key);
  const at = others.filter((i) => i.offsetLeft + i.offsetWidth / 2 < centre).length;
  const keys = dragOrder.value.filter((k) => k !== drag.key);
  keys.splice(at, 0, drag.key);
  if (keys.join("|") !== dragOrder.value.join("|")) dragOrder.value = keys;
}

function onDragEnd() {
  if (drag?.started && dragOrder.value) {
    setShown(dragOrder.value);
    // The mouse-up lands on the tab and would click it
    suppressClick = true;
    setTimeout(() => (suppressClick = false), 0);
  }
  cleanupDrag();
}

function cleanupDrag() {
  if (drag?.timer) clearTimeout(drag.timer);
  window.removeEventListener("pointermove", onDragMove);
  window.removeEventListener("pointerup", onDragEnd);
  window.removeEventListener("pointercancel", onDragEnd);
  window.removeEventListener("touchmove", blockScroll);
  drag = null;
  dragKey.value = null;
  dragOrder.value = null;
  dragDx.value = 0;
}

function onTabClick(key) {
  if (suppressClick) return;
  setActive(key);
}

onBeforeUnmount(cleanupDrag);

function setActive(key) {
  const tab = props.tabs.find((t) => t.key === key);
  if (!tab || tab.disabled) return;

  activeTab.value = key;
  emit("tab-change", key);

  nextTick(() => {
    const el = tabBody.value;
    if (!el) return;
    el.scrollTop = 0;
    wakeScroll();
  });
}

function setDefaultTab() {
  const fallback = props.tabs[0]?.key;

  const wanted = isMobile.value
    ? props.defaultActiveMobile || fallback
    : customDefault.value || props.defaultActiveDesktop || fallback;
  // A default that is not showing (removed, or on another device) falls back to the first tab that is
  const key = visibleTabs.value.some((t) => t.key === wanted) ? wanted : visibleTabs.value[0]?.key ?? fallback;

  activeTab.value = key;
}

function updateDevice() {
  const wasMobile = isMobile.value;
  isMobile.value = window.innerWidth <= 768;
  if (wasMobile !== isMobile.value) nextTick(setDefaultTab);
}

onMounted(() => {
  updateDevice();
  setDefaultTab();
  wakeScroll();
  window.addEventListener("resize", updateDevice);
});

onBeforeUnmount(() => {
  window.removeEventListener("resize", updateDevice);
});
defineExpose({ setActive });
</script>

<style scoped lang="scss">
