  display: flex;
  flex-direction: column;
  width: 100%;
  height: 100%;

  &__header-wrapper {
    flex-shrink: 0;
    border-bottom: rem-calc(1) solid var(--fu-border);
    background: var(--fu-surface-background);
  }

  &__content-wrapper {
    display: flex;
    flex-direction: column;
    flex: 1 1 auto;
    overflow: hidden;
    height: 100%;
  }

  &__body {
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    overflow-x: hidden;
    // padding: 0.5rem;
    background: var(--fu-content-body);
    margin-bottom: rem-calc(10);
    scroll-behavior: smooth;
    -webkit-overflow-scrolling: touch;
    overscroll-behavior: contain;
    touch-action: pan-y;
    transform: translateZ(0);
  }

  &__footer {
    flex-shrink: 0;
    border-top: rem-calc(1) solid var(--fu-border);
    background-color: var(--fu-surface-background);
    padding: 0.75rem 1rem;
    position: sticky;
    bottom: 0;
    z-index: 10;

    // Nothing in it: take no room
    &:empty {
      display: none;
    }
  }

  .fu-tab {
    display: inline-flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.75rem 1rem;
    border: none;
    background: transparent;
    cursor: pointer;
    font-weight: 500;
    color: #808080;
    transition: color 0.2s, border-color 0.2s;
    flex-shrink: 0;
    /*
     * Every tab carries the 2px underline space, transparent until active. Only the active tab used to have
     * a border, so it was 2px taller and its icon and label sat higher than its neighbours.
     */
    border-bottom: rem-calc(2) solid transparent;

    &--active {
      color: var(--fu-color-text);
      border-bottom-color: var(--fu-color-surface-gray-6);
    }

    &:hover:not(:disabled) {
      color: var(--fu-color-text);
    }

    &:disabled {
      cursor: not-allowed;
      opacity: 0.5;
    }

    /* AVATAR */
    &__avatar {
      width: rem-calc(28);
      height: rem-calc(28);
      border-radius: 50%;
      overflow: hidden;
      flex-shrink: 0;
      display: flex;
