      justify-content: center;
      font-weight: 600;
      color: #333;
      font-size: rem-calc(12);
      border-radius: 50%;
    }

    &__icon {
      display: flex;
    }

    &__title {
      white-space: nowrap;
    }

    /* Renaming: the title is a field in place of the tab */
    &--renaming {
      cursor: text;
