      background: var(--fu-content-body);
      color: var(--fu-color-text);
      font: inherit;
    }

    &__count {
      /* The tab's own gap already spaces it from the title */
      min-width: rem-calc(20);
      height: rem-calc(20);
      padding: 0 rem-calc(6);

      display: inline-flex;
      align-items: center;
      justify-content: center;

      font-size: rem-calc(12);
      font-weight: 600;
      line-height: 1;

      border-radius: rem-calc(999);
      /* A soft pill with readable text in both themes (it was mid-grey with dark text) */
      background: color-mix(in srgb, var(--fu-color-text) 12%, transparent);
      color: var(--fu-color-text);

      flex-shrink: 0;
    }

    &--active &__count {
      background: var(--fu-color-primary);
      color: #fff;
    }
  }
}

/* No background of its own: the strip sits on the page colour, with only the line under it */
.fu-tabs--plain .fu-tabs__header-wrapper {
  background: transparent;
}

/*
 * Each tab sits in an item so its ... can be a sibling of the button (a button cannot hold another).
 * On hover the ... takes the icon's place, like Jira. It stays while its menu is open.
 */
.fu-tab-item {
  position: relative;
  display: inline-flex;
  flex-shrink: 0;

  &.is-custom {
    /* A press must not select text or open the browser's touch menu: it can start a drag */
    user-select: none;
    -webkit-touch-callout: none;
    cursor: grab;
  }

  /* While a tab is dragged, the place it will land is marked with the shared pin and line */
  &.is-dragging {
    @include fu-drop-marker;
  }
}

/* The tab itself: when dragged it lifts off the row as a floating card and follows the pointer */
.fu-tab-item__body {
  position: relative;
  display: inline-flex;
}

.fu-tab-item.is-dragging .fu-tab-item__body {
  @include fu-drag-lifted;
  z-index: 5;
}

.fu-tabs-buttons.is-dragging {
  user-select: none;
}

.fu-tab__menu {
  position: absolute;
  left: rem-calc(10);
  top: 50%;
  transform: translateY(-50%);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.12s ease;
}

.fu-tab-item.is-custom:hover .fu-tab__menu,
.fu-tab-item.is-custom:focus-within .fu-tab__menu,
.fu-tab-item.is-menu-open .fu-tab__menu {
  opacity: 1;
  pointer-events: auto;
}

.fu-tab-item.is-custom:hover .fu-tab__icon,
.fu-tab-item.is-custom:focus-within .fu-tab__icon,
.fu-tab-item.is-menu-open .fu-tab__icon {
  opacity: 0;
}

/*
 * Touch screens have no hover, so the ... could never be reached. There it shows on the active tab, after
 * its title (the icon stays), and the active tab gets room for it.
 */
@media (hover: none) {
  .fu-tab-item.is-custom.is-active {
    .fu-tab {
      padding-right: rem-calc(40);
    }

    .fu-tab__menu {
      left: auto;
      right: rem-calc(6);
      opacity: 1;
      pointer-events: auto;
    }

    &:hover .fu-tab__icon,
    &:focus-within .fu-tab__icon {
      opacity: 1;
    }
  }
}

/* The + sits in the tab row, straight after the last tab */
.fu-tabs__add {
  flex: 0 0 auto;
  align-self: center;
  display: inline-flex;
  margin-left: rem-calc(4);
}

.fu-tabs-buttons {
  display: flex;
  flex-wrap: nowrap;
  overflow-x: auto;
  overflow-y: hidden;
  white-space: nowrap;
  gap: 0.25rem;
  z-index: 1;
  position: relative;
}
