<script setup lang="ts">
/**
 * FusionTreePicker
 * Pick one row from a tree (a task and its subtasks, a client and its budgets).
 * Draws proper elbow connectors, opens and closes branches, and can search.
 */
import { computed, ref, watch, type Component } from "vue";
import { ChevronRight, Minus, Plus, Search, X } from "@lucide/vue";

export interface TreePickerNode {
    id: string | number;
    label: string;
    /** Small text on the right (a status, a count). */
    meta?: string;
    /** Colour of the meta text. */
    metaTone?: "default" | "success" | "warning" | "danger";
    /** Small coloured square before the label, any CSS colour. */
    color?: string;
    icon?: Component;
    disabled?: boolean;
    /** How much of a budget is used, 0 to 1 and over. Shows a small ring: green while under, red once over. */
    usage?: number;
    children?: TreePickerNode[];
}

interface Row {
    node: TreePickerNode;
    level: number;
    hasChildren: boolean;
    open: boolean;
    /** For each ancestor level (1..level-1) and this row: does that branch continue below? */
    chain: boolean[];
}

const props = withDefaults(
    defineProps<{
        nodes: TreePickerNode[];
        /** Selected id (v-model). */
        modelValue?: string | number | null;
        /** Ids of open branches (v-model:expanded). When omitted the picker manages it. */
        expanded?: (string | number)[];
        /** Start with every branch open. */
        startExpanded?: boolean;
        /** Show a search box. */
        searchable?: boolean;
        searchPlaceholder?: string;
        /** Show "Collapse all / Expand all" under the tree. */
        footer?: boolean;
        /** list: plain rows. panel: bordered card, for use inside a dropdown. */
        variant?: "list" | "panel";
        /** Height of the scrolling area (CSS value). */
        maxHeight?: string;
        indent?: number;
        emptyText?: string;
        /** sm: tighter rows and smaller text, for a dropdown inside a form. */
        size?: "sm" | "md";
        /** What opens a branch: a chevron, or a small circle with + and - (the way Productive draws it). */
        toggle?: "chevron" | "circle";
    }>(),
    {
        modelValue: null,
        startExpanded: true,
        searchable: false,
        searchPlaceholder: "Type to search",
        footer: false,
        variant: "list",
        indent: 20,
        emptyText: "Nothing matches",
        size: "md",
        toggle: "chevron",
    },
);

const emit = defineEmits<{
    (e: "update:modelValue", id: string | number): void;
    (e: "update:expanded", ids: (string | number)[]): void;
    (e: "select", node: TreePickerNode): void;
}>();

const query = ref("");

function allParentIds(list: TreePickerNode[], out: (string | number)[] = []) {
    list.forEach((n) => {
        if (n.children?.length) {
            out.push(n.id);
            allParentIds(n.children, out);
        }
    });
    return out;
}

const innerExpanded = ref<(string | number)[]>(props.startExpanded ? allParentIds(props.nodes) : []);
watch(
    () => props.nodes,
    () => {
        if (props.startExpanded && props.expanded === undefined) innerExpanded.value = allParentIds(props.nodes);
    },
);
const openIds = computed(() => props.expanded ?? innerExpanded.value);

function setExpanded(ids: (string | number)[]) {
    innerExpanded.value = ids;
    emit("update:expanded", ids);
}

function toggle(id: string | number) {
    setExpanded(openIds.value.includes(id) ? openIds.value.filter((i) => i !== id) : [...openIds.value, id]);
}

/** With a search, keep rows that match plus their ancestors, and open those ancestors. */
const matches = computed(() => {
    const q = query.value.trim().toLowerCase();
    if (!q) return null;
    const keep = new Set<string | number>();
    const walk = (n: TreePickerNode, trail: (string | number)[]): boolean => {
        const self = n.label.toLowerCase().includes(q);
        let child = false;
        n.children?.forEach((c) => {
            if (walk(c, [...trail, n.id])) child = true;
        });
        if (self || child) {
            keep.add(n.id);
            trail.forEach((t) => keep.add(t));
        }
        return self || child;
    };
    props.nodes.forEach((n) => walk(n, []));
    return keep;
});

const rows = computed<Row[]>(() => {
    const out: Row[] = [];
    const filtered = (list: TreePickerNode[]) => (matches.value ? list.filter((n) => matches.value!.has(n.id)) : list);
    const visit = (list: TreePickerNode[], level: number, chain: boolean[]) => {
        const shown = filtered(list);
        shown.forEach((n, i) => {
            const hasChildren = !!n.children?.length;
            const open = matches.value ? true : openIds.value.includes(n.id);
            const nextChain = [...chain, i < shown.length - 1];
            out.push({ node: n, level, hasChildren, open, chain: nextChain });
            if (hasChildren && open) visit(n.children!, level + 1, nextChain);
        });
    };
    /* Top level rows have no connector. Their children start a fresh chain. */
    filtered(props.nodes).forEach((n) => {
        const hasChildren = !!n.children?.length;
        const open = matches.value ? true : openIds.value.includes(n.id);
        out.push({ node: n, level: 0, hasChildren, open, chain: [] });
        if (hasChildren && open) visit(n.children!, 1, []);
    });
    return out;
});

/** Vertical lines for ancestors that still have rows below. Position is relative to the row, in px. */
function guidesOf(r: Row): number[] {
    const out: number[] = [];
    const centre = props.size === "sm" ? 12 : 14;
    for (let j = 1; j < r.level; j++) if (r.chain[j - 1]) out.push((j - 1 - r.level) * props.indent + centre);
    return out;
}

function pick(r: Row) {
    /* A row that cannot be picked but has children (a client in a budget list) opens and closes instead */
    if (r.node.disabled) {
        if (r.hasChildren) toggle(r.node.id);
        return;
    }
    emit("update:modelValue", r.node.id);
    emit("select", r.node);
}

const hasAnyBranch = computed(() => allParentIds(props.nodes).length > 0);
</script>

<template>
    <div class="fu-treepicker" :class="[`fu-treepicker--${variant}`, `fu-treepicker--${size}`]" :style="{ '--fu-tp-indent': `${indent}px` }">
        <div v-if="searchable" class="fu-treepicker__search">
            <Search :size="16" class="fu-treepicker__search-icon" />
            <input v-model="query" type="text" :placeholder="searchPlaceholder" :aria-label="searchPlaceholder" />
            <button v-if="query" type="button" class="fu-treepicker__clear" aria-label="Clear search" @click="query = ''">
                <X :size="14" />
            </button>
        </div>

        <div class="fu-treepicker__scroll customScrollBar" :style="maxHeight ? { maxHeight } : undefined" role="tree">
            <div
                v-for="r in rows"
                :key="r.node.id"
                class="fu-treepicker__row"
                :style="{ marginLeft: `${r.level * indent}px` }"
                role="treeitem"
                :aria-selected="modelValue === r.node.id"
                :aria-expanded="r.hasChildren ? r.open : undefined"
            >
                <template v-if="r.level > 0">
                    <span v-for="g in guidesOf(r)" :key="g" class="fu-treepicker__guide" :style="{ left: `${g}px` }" />
                    <span class="fu-treepicker__elbow" />
                    <span v-if="r.chain[r.chain.length - 1]" class="fu-treepicker__continue" />
                </template>

                <button
                    type="button"
                    class="fu-treepicker__item"
                    :class="{
                        'is-selected': modelValue === r.node.id,
                        'is-disabled': r.node.disabled && !r.hasChildren,
                        'is-heading': r.node.disabled && r.hasChildren,
                    }"
                    :aria-disabled="r.node.disabled && !r.hasChildren ? true : undefined"
                    @click="pick(r)"
                >
                    <span
                        v-if="r.hasChildren"
                        class="fu-treepicker__chevron"
                        :class="{ 'is-open': r.open && $props.toggle === 'chevron', 'is-circle': $props.toggle === 'circle' }"
                        role="button"
                        :aria-label="r.open ? 'Collapse' : 'Expand'"
                        @click.stop="toggle(r.node.id)"
                    >
                        <template v-if="$props.toggle === 'circle'">
                            <Minus v-if="r.open" :size="10" />
                            <Plus v-else :size="10" />
                        </template>
                        <ChevronRight v-else :size="14" />
                    </span>
                    <span v-else class="fu-treepicker__chevron fu-treepicker__chevron--empty" />
                    <slot name="node" :node="r.node" :selected="modelValue === r.node.id" :level="r.level">
                        <component :is="r.node.icon" v-if="r.node.icon" :size="16" class="fu-treepicker__icon" />
                        <span v-else-if="r.node.color" class="fu-treepicker__swatch" :style="{ background: r.node.color }" />
                        <span class="fu-treepicker__label">{{ r.node.label }}</span>
                        <span v-if="r.node.meta" class="fu-treepicker__meta" :class="`is-${r.node.metaTone || 'default'}`">{{
                            r.node.meta
                        }}</span>
                        <svg
                            v-if="r.node.usage != null"
                            class="fu-treepicker__ring"
                            :class="{ 'is-over': r.node.usage > 1 }"
                            viewBox="0 0 24 24"
                            role="img"
                            :aria-label="`${Math.round(r.node.usage * 100)}% used`"
                        >
                            <circle cx="12" cy="12" r="9" class="fu-treepicker__ring-track" />
                            <circle
                                cx="12"
                                cy="12"
                                r="9"
                                class="fu-treepicker__ring-fill"
                                transform="rotate(-90 12 12)"
                                :stroke-dasharray="`${Math.min(Math.max(r.node.usage, 0), 1) * 56.55} 56.55`"
                            />
                        </svg>
                    </slot>
                </button>
            </div>
            <p v-if="!rows.length" class="fu-treepicker__empty">{{ emptyText }}</p>
        </div>

        <div v-if="footer && hasAnyBranch" class="fu-treepicker__footer">
            <button type="button" @click="setExpanded([])">Collapse all</button>
            <button type="button" @click="setExpanded(allParentIds(nodes))">Expand all</button>
        </div>
    </div>
</template>

